<template>
  <main class="runner-page">
    <header class="runner-header"><router-link class="back" to="/mine" aria-label="返回我的"><RunnerIcon name="back"/></router-link><div><span class="eyebrow">我的跑步记录</span><h1>{{ current.title }}</h1></div><span class="header-icon"><RunnerIcon :name="view"/></span></header>
    <nav class="runner-nav" aria-label="跑者档案导航"><router-link v-for="item in views" :key="item.id" :to="{path:'/runner',query:{view:item.id}}" :class="{on:view===item.id}" :aria-current="view===item.id?'page':undefined">{{ item.short }}</router-link></nav>
    <section v-if="!loggedIn" class="runner-card empty-large"><span class="empty-emblem"><RunnerIcon name="lock"/></span><h2>你的每一程，值得被收藏</h2><p>登录后查看运动数据、赛事生涯与私人收藏。</p><button type="button" class="runner-primary" @click="login">登录，开启我的记录</button></section>
    <section v-else-if="loading && !data" class="runner-card skeleton" aria-label="正在整理跑者档案" aria-busy="true"><i></i><i></i><i></i><p>正在整理你的跑步故事…</p></section>
    <section v-else-if="error" class="runner-card empty-large" role="alert"><span class="empty-emblem"><RunnerIcon name="stats"/></span><h2>这次没能加载出来</h2><p>{{ error }}</p><button class="runner-primary" type="button" @click="load">重新加载</button></section>
    <template v-else-if="data">
      <template v-if="view === 'stats'">
        <nav class="segmented" aria-label="运动统计周期"><button v-for="item in periods" :key="item.id" :class="{on:period===item.id}" type="button" :aria-pressed="period===item.id" @click="changePeriod(item.id)">{{ item.label }}</button></nav>
        <section class="runner-card training-card" :aria-busy="loading"><div class="period-control"><button type="button" aria-label="上一统计周期" :disabled="period==='all'||loading" @click="changeOffset(-1)">‹</button><h2>{{ training.label }}</h2><button type="button" aria-label="下一统计周期" :disabled="offset===0||period==='all'||loading" @click="changeOffset(1)">›</button></div><p class="kicker">跑步里程 <small>公里</small></p><div class="training-distance">{{ number(training.km) }}<span class="distance-decoration" aria-hidden="true">KM</span></div><div class="training-metrics"><div><b>{{ training.count }}</b><span>运动次数</span></div><div><b>{{ training.durationLabel || clock(training.durationSec) }}</b><span>运动时长</span></div><div><b>{{ training.paceLabel || '—' }}</b><span>平均配速 / 公里</span></div></div><RunnerBars :items="training.bars" :caption="period==='week'||period==='month'?'每日跑量 · 公里':period==='year'?'每月跑量 · 公里':'历年跑量 · 公里'"/></section>
        <section v-if="period==='week'" class="runner-card weekly-report"><div class="section-heading"><h2>这一周的跑步手记</h2><span class="small-pill">周报</span></div><p class="weekly-copy">{{ training.count ? `你在 ${training.activeDays} 天里，完成了 ${training.count} 次出发。` : offset === 0 ? '这一周的故事，等你来写。' : '这一周没有记录运动。' }}</p><div class="report-stats"><div><span>跑了这么远</span><b>{{ number(training.km) }}<small> km</small></b></div><div><span>和自己相处</span><b>{{ Math.round((training.durationSec||0)/60) }}<small> 分钟</small></b></div></div><p class="report-compare">{{ comparison }}</p><router-link v-if="!training.count" class="text-link" to="/sport">记录一次跑步 <span>›</span></router-link></section>
        <section class="runner-card"><div class="section-heading"><h2>运动明细</h2><router-link class="text-link" to="/sport">记录 / 管理 <span>›</span></router-link></div><div v-for="run in training.runs" :key="run.id" class="run-line"><span class="run-date">{{ run.startedAt.slice(5,10).replace('-','.') }}<small>{{ run.startedAt.slice(0,4) }}</small></span><div><b>{{ runTypeLabel(run) }}</b><span>{{ run.city || '个人运动记录' }} · {{ run.source==='manual'?'手动记录':run.source==='file'?'文件导入':'同步记录' }}</span></div><strong>{{ number(run.distanceKm) }}<small>公里</small></strong></div><div v-if="!training.runs?.length" class="inline-empty"><RunnerIcon name="stats"/><p>还没有运动记录</p><router-link to="/sport" class="text-link">记下第一公里 ›</router-link></div><p v-if="training.truncated" class="subtle">展示最近 100 条，统计包含本周期全部记录。</p></section>
      </template>
      <template v-else-if="view === 'career'">
        <router-link class="runner-card history-entry" to="/history"><span class="eyebrow">我的跑步记录</span><h2>打开我的跑史 <span>↗</span></h2><p>找回旧比赛，把成绩变化与自己的感受写成回顾。</p></router-link>
        <section class="runner-card career-hero"><span class="eyebrow">记录每一次完赛</span><div class="career-head"><div><p class="kicker">累计完赛</p><b class="career-count">{{ career.finished }}<small>场</small></b></div><span class="hero-medal"><RunnerIcon name="career"/></span></div><div class="career-splits"><div v-for="item in career.byDistance" :key="item.key"><b>{{ item.count }}</b><span>{{ item.label }}</span></div></div><div class="career-secondary"><div><b>{{ career.raceYears || 0 }}<small> 年</small></b><span>赛事跨度</span></div><div><b>{{ number(career.totalKm) }}</b><span>比赛里程 / 公里</span></div><div><b>{{ career.totalTime || clock(career.totalSeconds) }}</b><span>累计完赛时间</span></div></div><div class="runner-achievement-entry"><span>{{ posterAvailable ? '把完赛记录留作纪念' : '记录有效的完赛成绩后，即可制作海报' }}</span><router-link v-if="posterAvailable" :to="{ path: '/achievement-poster', query: { returnTo: '/runner?view=career' } }">制作成绩海报 <RunnerIcon name="arrow" /></router-link><router-link v-else to="/">去记录成绩 ›</router-link></div></section>
        <section class="runner-card"><div class="section-heading"><h2>我的最好成绩</h2><span class="subtle">个人记录 · 未核验</span></div><router-link v-for="pb in career.pb" :key="pb.distance" class="personal-best" :to="'/races/'+pb.race.id"><div><span class="pb-tag">个人最好成绩</span><h3>{{ pb.distanceLabel }}</h3><p>{{ pb.race.name }}</p><span class="subtle">{{ pb.race.raceDate }}</span></div><strong>{{ pb.clock }}<RunnerIcon name="arrow"/></strong></router-link><div v-if="!career.pb?.length" class="inline-empty"><RunnerIcon name="career"/><p>每一个 PB，都从第一次完赛开始</p><router-link to="/" class="text-link">找到你的下一场比赛 ›</router-link></div></section>
        <section class="runner-card"><div class="section-heading"><h2>成长的刻度</h2><span class="subtle">历年赛事</span></div><nav class="metric-tabs" aria-label="赛事趋势指标"><button v-for="item in trendMetrics" :key="item.id" type="button" :class="{on:trendMetric===item.id}" :aria-pressed="trendMetric===item.id" @click="trendMetric=item.id">{{ item.label }}</button></nav><template v-if="career.trends?.length"><div v-if="trendMetric==='paceSec'" class="pace-history" role="group" aria-label="历年平均配速"><p class="pace-history-note">数值越小，配速越快<span>分 / 公里</span></p><div v-for="item in trendItems" :key="item.year" class="pace-history-row"><span>{{ item.year }} 年</span><strong>{{ pace(item.paceSec) }}</strong></div><p class="subtle">仅统计距离可计算的成绩；没有有效距离时显示 —。</p></div><RunnerBars v-else :items="trendItems" :field="trendMetric" :unit="trendUnit" :format="trendFormat" :caption="'历年' + trendMetrics.find(x=>x.id===trendMetric).label"/></template><p v-else class="blank-copy">添加完赛成绩后，这里会记录你的成长。</p></section>
        <section class="timeline-section"><div class="section-heading"><h2>我的赛事时光轴</h2><router-link class="text-link" to="/">添加成绩 <span>＋</span></router-link></div><div class="filter-row"><select v-model="year" aria-label="赛事年份"><option value="">全部年份</option><option v-for="item in career.years" :key="item" :value="String(item)">{{ item }} 年</option></select><nav class="kind-pills" aria-label="赛事类型"><button v-for="kind in kinds" :key="kind.id" type="button" :class="{on:kindFilter===kind.id}" @click="kindFilter=kind.id">{{ kind.label }}</button></nav></div><div v-if="!filteredResults.length" class="runner-card inline-empty"><RunnerIcon name="calendar"/><p>{{ data.results.length?'这个筛选下还没有记录':'从第一场比赛，写下你的跑步故事' }}</p><router-link to="/" class="text-link">去找一场比赛 ›</router-link></div><router-link v-for="result in filteredResults" :key="result.race.id+result.distance" class="timeline-item" :to="'/races/'+result.race.id"><div class="timeline-date"><b>{{ result.race.raceDate.slice(5,10).replace('-','.') }}</b><span>{{ result.race.raceDate.slice(0,4) }}</span></div><article><div class="timeline-top"><span>{{ result.distanceLabel }}</span><i v-if="isRoadPb(result)">PB</i></div><h3>{{ result.race.name }}</h3><p>{{ result.race.city || result.race.province || '比赛地点未记录' }}</p><div class="timeline-bottom"><strong>{{ result.clock }}</strong><span>{{ result.pace || '—' }} / km <RunnerIcon name="arrow"/></span></div></article></router-link></section>
      </template>
      <template v-else-if="view === 'footprints'">
        <section class="passport"><div class="passport-top"><span>城市护照</span><RunnerIcon name="footprints"/></div><h2>用脚步，认识一座城。</h2><p>每一次完赛，都是属于你的城市纪念。</p><div class="passport-metrics"><div><b>{{ places.length }}</b><span>座完赛城市</span></div><div><b>{{ provinceCount }}</b><span>个省级地区</span></div><div><b>{{ footprintCount }}</b><span>场赛事记忆</span></div></div><div class="passport-bottom"><span>{{ year ? year+' 年足迹' : '我的赛事城市护照' }}</span><span>用脚步探索城市</span></div></section>
        <div class="section-heading footprint-filter"><h2>点亮的城市</h2><select v-model="year" aria-label="足迹年份"><option value="">全部年份</option><option v-for="item in career.years" :key="item" :value="String(item)">{{ item }} 年</option></select></div><div class="city-stamps"><button v-for="(place,i) in places" :key="place.key" type="button" :class="{selected:selectedCity===place.key}" :aria-pressed="selectedCity===place.key" @click="selectedCity=selectedCity===place.key?'':place.key"><span class="stamp-index">NO. {{ String(i+1).padStart(2,'0') }}</span><RunnerIcon name="footprints"/><b>{{ place.name }}</b><span>{{ place.province === place.name ? '城市赛事纪念' : place.province || '赛事足迹' }}</span><i>{{ place.count }} 场完赛 · {{ place.latest.slice(0,7).replace('-','.') }}</i></button></div><section v-if="!places.length" class="runner-card empty-large"><span class="empty-emblem"><RunnerIcon name="footprints"/></span><h2>第一枚城市印章，等你来点亮</h2><p>保存带有城市信息的完赛成绩后，城市会出现在这里。</p><router-link to="/" class="runner-primary">看看想去的比赛</router-link></section><section v-if="selectedCity" class="runner-card city-detail"><div class="section-heading"><h2>{{ selectedPlace?.name }} · 我的比赛</h2><button class="text-link" type="button" @click="selectedCity=''">收起</button></div><router-link v-for="result in cityResults" :key="result.race.id+result.distance" class="city-result" :to="'/races/'+result.race.id"><div><h3>{{ result.race.name }}</h3><p>{{ result.race.raceDate }} · {{ result.distanceLabel }}</p></div><b>{{ result.clock }}</b></router-link></section><p class="privacy-note">根据已保存的赛事城市归档，不记录实时位置。</p>
      </template>
      <template v-else-if="view === 'honors' || view === 'media'">
        <section class="collection-banner" :class="view"><div><span class="eyebrow">{{ view==='honors'?'完赛纪念':'赛事影像' }}</span><h2>{{ view==='honors'?'你的热爱，有迹可藏。':'让那一刻，再次鲜活。' }}</h2><p>{{ view==='honors'?'收藏证书与奖牌，珍藏每一场努力。':'照片与视频，收进自己的赛事记忆。' }}</p></div><RunnerIcon :name="view"/></section>
        <div class="gallery-toolbar"><nav class="segmented" :aria-label="view==='honors'?'荣誉类型':'影像类型'"><button v-for="kind in galleryKinds" :key="kind.id" type="button" :class="{on:galleryKind===kind.id}" @click="galleryKind=kind.id">{{ kind.label }} <small>{{ allMedia.filter(x=>x.kind===kind.id).length }}</small></button></nav><button type="button" class="upload-button" @click="openUpload"><RunnerIcon name="add"/>上传</button></div><div class="filter-row gallery-filter"><span class="subtle">仅自己可见 · 原图保留</span><select v-model="year" aria-label="收藏年份"><option value="">全部年份</option><option v-for="item in collectionYears" :key="item" :value="item">{{ item }} 年</option></select></div>
        <section v-if="!gallery.length" class="runner-card empty-large"><span class="empty-emblem"><RunnerIcon :name="view"/></span><h2>{{ emptyCollectionTitle }}</h2><p>{{ data.results.length?'选一场已记录成绩的比赛，上传属于你的纪念。':'先在赛事详情中保存完赛成绩，再来收藏证书、奖牌与影像。' }}</p><button v-if="data.results.length" type="button" class="runner-primary" @click="openUpload">上传我的第一份收藏</button><router-link v-else to="/" class="runner-primary">去添加完赛成绩</router-link></section>
        <section v-for="group in galleryGroups" :key="group.year" class="gallery-year"><h2>{{ group.year }}<span>{{ group.items.length }} 份收藏</span></h2><div class="gallery-grid"><article v-for="item in group.items" :key="item.key" class="gallery-item"><button type="button" class="media-cover" :class="item.kind" :aria-label="'预览'+item.race.name" @click="openPreview(item)"><video v-if="item.kind==='video'" :src="item.src" preload="metadata" muted playsinline></video><img v-else :src="item.src" :alt="item.race.name+' '+mediaLabel(item.kind)" loading="lazy"/><span v-if="item.kind==='video'" class="play-mark">▶</span><span class="media-kind">{{ mediaLabel(item.kind) }}</span></button><h3>{{ item.race.name }}</h3><div class="media-meta"><span>{{ item.race.raceDate }} · {{ item.distanceLabel }}</span><button v-if="!item.legacy" class="media-delete" type="button" :aria-label="'删除'+item.race.name+mediaLabel(item.kind)" @click="askDelete(item)">删除</button></div><router-link v-if="item.legacy" class="legacy-link" :to="'/races/'+item.race.id">在赛事详情管理 ›</router-link></article></div></section><p class="privacy-note"><RunnerIcon name="lock"/>私人收藏，不作为官方成绩核验。</p>
      </template>
      <template v-else-if="view === 'devices'">
        <section class="runner-card device-import-card" :aria-busy="deviceBusy==='import'">
          <div class="device-import-top"><span class="device-wordmark">COROS <small>高驰</small></span><span class="small-pill">文件导入</span></div>
          <h2>跑过的每一程，<br/>都值得好好记录。</h2>
          <p>把设备平台导出的运动文件带到这里，跑量、配速与每周积累会一起更新。</p>
          <label class="device-file-button" :class="{busy:deviceBusy}"><RunnerIcon name="add"/><span>{{ deviceBusy==='import'?'正在读取运动记录…':'导入运动文件' }}</span><input aria-label="选择 FIT 或 TCX 运动文件" type="file" accept=".fit,.tcx" :disabled="!!deviceBusy" @change="importActivity"/></label>
          <div class="device-import-meta"><span>FIT / TCX · 单场运动 · ≤ 5 MB</span><router-link to="/sport">手动记录 ›</router-link></div>
          <div v-if="deviceMessage" class="device-feedback" :class="{failure:deviceFailed}" :role="deviceFailed?'alert':'status'"><p>{{ deviceMessage }}</p><router-link v-if="!deviceFailed" to="/sport">查看运动记录 ›</router-link></div>
          <details class="device-guide"><summary>如何准备运动文件？ <span>查看步骤</span></summary><ol><li><b>打开一场活动</b><span>在高驰、佳明、颂拓等设备 App 中，打开一场已完成的跑步活动。</span></li><li><b>导出运动数据</b><span>查看当前 App 提供的导出选项，保存可用的 FIT / TCX 文件。菜单位置以实际版本为准，不要选择轨迹图片。</span></li><li><b>回到这里导入</b><span>选择刚保存的文件。开始时间相差不超过 60 秒，且距离、用时接近时，更完整的 FIT 可补全现存记录。与现存记录差异过大时不会新增或覆盖，请先到运动页核对。</span></li></ol></details>
          <p class="device-import-privacy">仅保存运动摘要，不保留原文件、GPS 轨迹和心率。</p>
          <nav class="device-legal-links" aria-label="运动数据保护说明"><router-link to="/legal/privacy">隐私政策</router-link><router-link to="/legal/permissions">权限说明</router-link></nav>
          <p class="device-import-rule">文件导入按跑团的手填规则计入 PK；类型待确认、越野缺少爬升时，先计个人运动。不作为厂商官方同步或赛事成绩认证。</p>
        </section>
        <section class="runner-card device-connections"><div class="section-heading"><h2>自动同步</h2><span class="subtle">连接与授权</span></div><p class="device-section-copy">开通厂商授权后，完成活动即可同步。你可以随时解除连接，保留已保存的运动。</p><article v-for="device in data.devices" :key="device.id" class="device-connection"><div class="device-row"><span class="device-monogram" :class="device.id">{{ device.name.slice(0,1).toUpperCase() }}</span><div><h3>{{ device.name }}</h3><p>{{ device.error || device.reason || (device.status==='connected'?'跑步与越野记录同步中':'可在厂商页面安全授权') }}</p><p v-if="device.lastSyncedAt" class="device-sync-time">上次同步 {{ syncTime(device.lastSyncedAt) }}</p></div><span class="device-status" :class="device.status">{{ deviceStatus(device.status) }}</span></div><div v-if="device.status==='available'||device.status==='connected'||device.status==='error'||device.status==='revoked'||device.canDisconnect" class="device-actions"><button v-if="device.status==='available'||device.status==='revoked'" class="device-action-primary" type="button" :disabled="!!deviceBusy" @click="connectDevice(device)">{{ deviceBusy===device.id?'正在打开…':'前往授权' }}</button><template v-else-if="device.status==='connected'||device.status==='error'"><button class="device-action-primary" type="button" :disabled="!!deviceBusy" @click="syncDevice(device)">{{ deviceBusy===device.id?'正在同步…':'立即同步' }}</button><button class="device-action-secondary" type="button" :disabled="!!deviceBusy" @click="askDisconnect(device)">解除连接</button></template><button v-else class="device-action-secondary" type="button" :disabled="!!deviceBusy" @click="askDisconnect(device)">清除旧连接</button></div></article><p class="subtle source-note">厂商自动同步需正式开通，连接状态以本页提示为准。授权仅在厂商官方页面进行，平台不会索取你的设备账号密码。</p></section>
        <section class="runner-card source-faq"><h2>关于运动数据</h2><details><summary>文件导入与自动同步有什么区别？</summary><p>文件由你从设备平台导出并上传，按手填规则参与跑团 PK。厂商自动同步需要正式授权与接入，只有开放后才会显示连接入口。两种方式都不会自动生成赛事完赛成绩。</p></details><details><summary>运动跑量和比赛里程有什么区别？</summary><p>运动统计来自运动页保存的跑步和越野原始距离；赛事生涯来自已保存的完赛成绩。两者单独展示，避免同一场比赛重复累加。</p></details><details><summary>为什么和跑团 PK 跑量不一样？</summary><p>个人运动统计展示原始跑步距离。跑团 PK 会按跑团规则计算有效跑量，越野折算、时间范围和审核规则可能不同。</p></details><details><summary>能直接同步 Apple 健康吗？</summary><p>当前网页和微信小程序不能直接读取 Apple 健康。本平台尚未提供连接；未来需通过具备 HealthKit 权限的原生应用接入。</p></details></section>
      </template>
      <template v-else-if="view === 'help'">
        <section class="runner-card help-intro"><RunnerIcon name="help"/><h2>少一点摸索，多一点奔跑。</h2><p>你可能想知道的，都整理在这里。</p></section><section class="runner-card source-faq"><details v-for="(item,i) in faqs" :key="item.title" :open="i===0"><summary>{{ item.title }}</summary><p>{{ item.text }}</p><router-link v-if="item.to" :to="item.to" class="text-link">{{ item.action }} ›</router-link></details></section><router-link class="help-footer" to="/news">查看赛事资讯与官方信息 <span>›</span></router-link>
      </template>
      <footer class="data-footer">统计更新至 {{ data.asOf }} · 仅统计本账号已保存的记录</footer>
    </template>
    <p v-if="notice" class="runner-notice" role="status">{{ notice }}</p>
    <dialog ref="uploadDialog" class="runner-dialog" @close="resetUpload" @cancel="uploading && $event.preventDefault()"><form @submit.prevent="submitUpload"><div class="dialog-head"><h2>收藏这一场</h2><button type="button" aria-label="关闭上传" :disabled="uploading" @click="uploadDialog.close()">×</button></div><p class="subtle">内容仅自己可见，可随时删除。</p><label>关联比赛<select v-model="uploadResult" :disabled="uploading" required><option value="" disabled>选择已保存成绩的比赛</option><option v-for="(result,i) in data?.results || []" :key="result.race.id+result.distance" :value="String(i)">{{ result.race.name }} · {{ result.distanceLabel }}</option></select></label><label>收藏类型<select v-model="uploadKind" :disabled="uploading" @change="uploadFile=null"><option v-for="kind in galleryKinds" :key="kind.id" :value="kind.id">{{ kind.label }}</option></select></label><label class="file-choice"><RunnerIcon name="add"/><span>{{ uploadFile?.name || (uploadKind==='video'?'选择一段视频':'选择一张照片') }}</span><input :key="uploadKind" type="file" :accept="uploadKind==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'" :disabled="uploading" @change="pickFile"/></label><p class="subtle">{{ uploadKind==='video'?'MP4 / WebM，最大 40 MB':'JPG / PNG / WebP，最大 8 MB' }}</p><p v-if="uploadError" role="alert" class="upload-error">{{ uploadError }}</p><button class="runner-primary" type="submit" :disabled="uploading||!uploadFile||uploadResult===''">{{ uploading?'正在上传，请稍候…':'保存到我的收藏' }}</button></form></dialog>
    <dialog ref="previewDialog" class="preview-dialog" @close="preview=null"><template v-if="preview"><div class="preview-head"><span>{{ mediaLabel(preview.kind) }} · 仅自己可见</span><button type="button" aria-label="关闭预览" @click="previewDialog.close()">×</button></div><video v-if="preview.kind==='video'" :src="preview.src" controls playsinline preload="metadata"></video><img v-else :src="preview.src" :alt="preview.race.name"/><h2>{{ preview.race.name }}</h2><p>{{ preview.race.raceDate }} · {{ preview.distanceLabel }} · 未核验</p></template></dialog>
    <dialog ref="activityConsentDialog" class="runner-dialog activity-consent-dialog" aria-labelledby="activity-consent-title" @cancel="cancelActivityFileConsent" @close="onActivityConsentClosed"><h2 id="activity-consent-title">导入运动数据前确认</h2><p>完整运动文件可能包含 GPS 轨迹、心率等敏感个人信息。</p><p>同意后，本次文件将临时上传并解析，仅保存运动摘要与去重信息，不保留原文件、GPS 轨迹和心率。跑量及相关截图按你所在跑团的规则展示。</p><p>取消不会上传，也不影响基本浏览。请阅读<router-link to="/legal/privacy" target="_blank" rel="noopener noreferrer">隐私政策</router-link>与<router-link to="/legal/permissions" target="_blank" rel="noopener noreferrer">权限说明</router-link>。</p><div><button class="runner-secondary" type="button" @click="cancelActivityFileConsent">取消</button><button class="runner-primary" type="button" @click="acceptActivityFileConsent">同意本次解析并导入</button></div></dialog>
    <dialog ref="disconnectDialog" class="runner-dialog disconnect-dialog"><h2>{{ disconnectItem?.status==='unavailable'?'清除旧连接？':'解除 '+(disconnectItem?.name||'设备')+' 连接？' }}</h2><p>{{ disconnectItem?.status==='unavailable'?'厂商接入尚未开通，将清除之前保留的连接凭据。':'解除后停止接收新的运动数据，' }}已保存的运动记录继续保留。你仍可自行管理和删除它们。</p><p v-if="disconnectError" class="upload-error" role="alert">{{ disconnectError }}</p><div><button class="runner-secondary" type="button" :disabled="!!deviceBusy" @click="disconnectDialog.close()">{{ disconnectItem?.status==='unavailable'?'暂不清除':'保持连接' }}</button><button class="runner-primary" type="button" :disabled="!!deviceBusy" @click="disconnectDevice">{{ deviceBusy?'正在处理…':disconnectItem?.status==='unavailable'?'清除旧连接':'解除连接' }}</button></div></dialog>
    <dialog ref="deleteDialog" class="runner-dialog delete-dialog"><h2>删除这份收藏？</h2><p>只删除这份文件，不影响比赛成绩。删除后无法恢复。</p><p v-if="deleteError" class="upload-error" role="alert">{{ deleteError }}</p><div><button class="runner-secondary" type="button" :disabled="deleting" @click="deleteDialog.close()">保留</button><button class="runner-primary" type="button" :disabled="deleting" @click="deleteMedia">{{ deleting?'正在删除':'删除收藏' }}</button></div></dialog>
  </main>
</template>
<script setup>
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { api, resultProofSrc, upload } from '../api';
import RunnerIcon from '../components/RunnerIcon.vue';
import RunnerBars from '../components/RunnerBars.vue';
import { normalizeResults } from '../achievement-model';
import { version as activityConsentVersion } from '../../../shared/legal-documents.json';
const route=useRoute(), router=useRouter();
const views=[{id:'stats',title:'运动数据',short:'运动'},{id:'career',title:'赛事生涯',short:'生涯'},{id:'footprints',title:'城市足迹',short:'足迹'},{id:'honors',title:'荣誉收藏',short:'荣誉'},{id:'media',title:'赛事影像',short:'影像'},{id:'devices',title:'数据来源',short:'设备'},{id:'help',title:'使用帮助',short:'帮助'}];
const view=computed(()=>views.some(x=>x.id===route.query.view)?route.query.view:'career');
const current=computed(()=>views.find(x=>x.id===view.value));
const loggedIn=ref(Boolean(localStorage.getItem('marathon_token')));
const data=ref(null), loading=ref(false), error=ref(''), notice=ref('');
const posterAvailable=computed(()=>normalizeResults(data.value).length>0);
const period=ref('week'), offset=ref(0), year=ref(''), kindFilter=ref('all'), trendMetric=ref('count'), selectedCity=ref('');
const periods=[{id:'week',label:'周'},{id:'month',label:'月'},{id:'year',label:'年'},{id:'all',label:'累计'}];
const kinds=[{id:'all',label:'全部'},{id:'road',label:'路跑'},{id:'trail',label:'越野'},{id:'other',label:'其他'}];
const allKinds=[{id:'certificate',label:'证书'},{id:'medal',label:'奖牌'},{id:'photo',label:'照片'},{id:'video',label:'视频'}];
const trendMetrics=[{id:'count',label:'完赛场数'},{id:'km',label:'比赛里程'},{id:'seconds',label:'完赛时间'},{id:'paceSec',label:'平均配速'}];
const training=computed(()=>data.value?.training||{}), career=computed(()=>data.value?.career||{});
let requestId=0,unmounted=false,noticeTimer,reportPositioned=false;
watch(notice,value=>{clearTimeout(noticeTimer);if(value)noticeTimer=setTimeout(()=>notice.value='',3600);});
watch([()=>route.query.report,view,data],async([report,currentView,payload])=>{if(report!=='1'){reportPositioned=false;return;}if(currentView==='stats'&&payload&&!reportPositioned){reportPositioned=true;await nextTick();if(!unmounted)document.querySelector('.weekly-report')?.scrollIntoView({block:'start',behavior:'instant'});}});
async function load(){if(!loggedIn.value)return;const id=++requestId;const sessionToken=localStorage.getItem('marathon_token');loading.value=true;error.value='';try{const value=await api(`/me/runner?period=${period.value}&offset=${offset.value}`);if(id===requestId&&!unmounted&&sessionToken===localStorage.getItem('marathon_token'))data.value=value;}catch(err){if(id!==requestId||unmounted||sessionToken!==localStorage.getItem('marathon_token'))return;if(err.status===401){loggedIn.value=false;data.value=null;}else error.value=err.message||'请检查网络后重试';}finally{if(id===requestId&&!unmounted)loading.value=false;}}
function login(){localStorage.setItem('marathon_return_after_login','/runner?view='+view.value);router.push('/mine');}
function changePeriod(value){if(period.value===value)return;period.value=value;offset.value=0;load();}
function changeOffset(delta){if(loading.value||period.value==='all')return;offset.value=Math.min(0,offset.value+delta);load();}
watch(view,()=>{cancelActivityFileConsent();year.value='';selectedCity.value='';galleryKind.value=view.value==='media'?'photo':'certificate';window.scrollTo({top:0,behavior:'instant'});});
onBeforeUnmount(()=>{unmounted=true;cancelActivityFileConsent();requestId++;clearTimeout(noticeTimer);});
const number=value=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
function clock(sec){const n=Math.round(Number(sec)||0);return`${Math.floor(n/3600)}:${String(Math.floor(n/60)%60).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function pace(sec){if(!Number.isFinite(sec)||sec<=0)return'—';const value=Math.round(sec);return`${Math.floor(value/60)}′${String(value%60).padStart(2,'0')}″`;}
const comparison=computed(()=>{const t=training.value;if(t.previousKm>0){const difference=Math.round((t.km-t.previousKm)*100)/100;return difference===0?'和上一周期一样稳稳向前。':`${offset.value===0?'比上周同期':'比上一周'}${difference>0?'多跑了':'少跑了'} ${number(Math.abs(difference))} 公里，按自己的节奏就好。`;}return t.km>0?(offset.value===0?'上周同期没有记录，这周已重新出发。':`上一周没有记录，该周完成了 ${number(t.km)} 公里。`):'不赶进度，找到适合自己的节奏。';});
const trendItems=computed(()=>(career.value.trends||[]).map(x=>({...x,label:String(x.year)})));
const trendUnit=computed(()=>({count:'场',km:'公里',seconds:''}[trendMetric.value]||''));
const trendFormat=computed(()=>trendMetric.value==='seconds'?clock:number);
const completedResults=computed(()=>(data.value?.results||[]).filter(x=>{
  const day=String(x.race.raceDate||'');
  const ms=Date.parse(day+'T00:00:00Z');
  return /^\d{4}-\d{2}-\d{2}$/.test(day)&&Number.isFinite(ms)&&new Date(ms).toISOString().slice(0,10)===day&&day<=data.value.asOf;
}));
const yearResults=computed(()=>completedResults.value.filter(x=>!year.value||x.race.raceDate.startsWith(year.value)));
const offlineResults=computed(()=>yearResults.value.filter(x=>x.race.meet!=='online'));
const isRoadPb=result=>result.race.meet!=='online'&&(result.race.kind||'road')==='road'&&(career.value.pb||[]).some(x=>x.distance===result.distance&&x.seconds===result.seconds);
const filteredResults=computed(()=>yearResults.value.filter(x=>kindFilter.value==='all'||(kindFilter.value==='other'?!['road','trail'].includes(x.race.kind||'road'):(x.race.kind||'road')===kindFilter.value)));
const provinceCount=computed(()=>new Set(offlineResults.value.map(x=>x.race.province).filter(Boolean)).size);
const footprintCount=computed(()=>new Set(offlineResults.value.map(x=>x.race.id)).size);
const places=computed(()=>{const map=new Map();for(const x of offlineResults.value){const name=x.race.city;if(!name)continue;const key=(x.race.province||'')+':'+name;if(!map.has(key))map.set(key,{key,name,province:x.race.province,ids:new Set(),latest:x.race.raceDate});const p=map.get(key);p.ids.add(x.race.id);if(x.race.raceDate>p.latest)p.latest=x.race.raceDate;}return[...map.values()].map(x=>({...x,count:x.ids.size})).sort((a,b)=>b.count-a.count||b.latest.localeCompare(a.latest));});
watch(year,()=>selectedCity.value='');
const selectedPlace=computed(()=>places.value.find(x=>x.key===selectedCity.value));
const cityResults=computed(()=>offlineResults.value.filter(x=>(x.race.province||'')+':'+x.race.city===selectedCity.value));
const galleryKind=ref(view.value==='media'?'photo':'certificate');
const galleryKinds=computed(()=>view.value==='honors'?allKinds.slice(0,2):allKinds.slice(2));
const allMedia=computed(()=>{if(!data.value)return[];const results=data.value.results||[];const archive=(data.value.media||[]).map(x=>{const result=results.find(r=>String(r.race.id)===String(x.raceId)&&r.distance===x.distance);const race=result?.race||x.race||{id:x.raceId,name:'赛事收藏',raceDate:''};return{...x,key:'media-'+x.id,race,distanceLabel:result?.distanceLabel||x.distanceLabel||x.distance,src:`${import.meta.env.BASE_URL.replace(/\/$/,'')}/api/me/runner/media/${x.id}/file?t=${encodeURIComponent(localStorage.getItem('marathon_token')||'')}`};}).filter(Boolean);const legacy=results.filter(x=>x.hasProof).map(x=>({key:'proof-'+x.race.id+'-'+x.distance,kind:x.proofLabel==='奖牌'?'medal':'certificate',race:x.race,distance:x.distance,distanceLabel:x.distanceLabel,legacy:true,src:resultProofSrc(x.race.id,x.distance)}));return[...archive,...legacy];});
const collectionYears=computed(()=>[...new Set(allMedia.value.map(x=>(x.race.raceDate||'').slice(0,4)).filter(x=>/^\d{4}$/.test(x)))].sort().reverse());
const gallery=computed(()=>allMedia.value.filter(x=>x.kind===galleryKind.value&&(!year.value||x.race.raceDate.startsWith(year.value))));
const galleryGroups=computed(()=>{const groups=new Map();for(const x of gallery.value){const y=(x.race.raceDate||'').slice(0,4)||'未记录年份';if(!groups.has(y))groups.set(y,[]);groups.get(y).push(x);}return[...groups].sort(([a],[b])=>b.localeCompare(a)).map(([year,items])=>({year,items}));});
const emptyCollectionTitle=computed(()=>({certificate:'给每一次完赛，一席珍藏',medal:'让奖牌成为努力的回声',photo:'把难忘的一刻，留在这里',video:'把冲线那一刻，再播放一次'}[galleryKind.value]));
const mediaLabel=kind=>allKinds.find(x=>x.id===kind)?.label||'收藏';
const uploadDialog=ref(null),previewDialog=ref(null),deleteDialog=ref(null),preview=ref(null),deleteItem=ref(null),uploadResult=ref(''),uploadKind=ref('certificate'),uploadFile=ref(null),uploading=ref(false),uploadError=ref(''),deleting=ref(false),deleteError=ref('');
function openUpload(){if(!data.value.results.length){notice.value='先在赛事详情保存完赛成绩，再来收藏影像。';return;}uploadKind.value=galleryKind.value;uploadError.value='';uploadDialog.value.showModal();}
function resetUpload(){if(uploading.value)return;uploadFile.value=null;uploadError.value='';uploadResult.value='';}
function pickFile(event){uploadError.value='';const file=event.target.files?.[0];uploadFile.value=null;if(!file)return;const isVideo=uploadKind.value==='video';if(!(isVideo?/^video\/(mp4|webm)$/:/^image\/(jpeg|png|webp)$/).test(file.type)){uploadError.value=isVideo?'请选择 MP4 或 WebM 视频':'请选择 JPG、PNG 或 WebP 图片';event.target.value='';return;}if(file.size>(isVideo?40:8)*1024*1024){uploadError.value=isVideo?'视频不能超过 40 MB':'图片不能超过 8 MB';event.target.value='';return;}uploadFile.value=file;}
async function submitUpload(){if(uploading.value||!uploadFile.value||uploadResult.value==='')return;const result=data.value.results[Number(uploadResult.value)];if(!result)return;uploading.value=true;uploadError.value='';try{await upload(`/me/runner/media?raceId=${encodeURIComponent(result.race.id)}&distance=${encodeURIComponent(result.distance)}&kind=${uploadKind.value}`,uploadFile.value);galleryKind.value=uploadKind.value;year.value='';notice.value='已保存到私人收藏';uploadDialog.value.close();await load();}catch(err){uploadError.value=err.message;}finally{uploading.value=false;if(!uploadDialog.value?.open)resetUpload();}}
async function openPreview(item){preview.value=item;await nextTick();previewDialog.value.showModal();}
function askDelete(item){deleteItem.value=item;deleteError.value='';deleteDialog.value.showModal();}
async function deleteMedia(){if(deleting.value||!deleteItem.value)return;deleting.value=true;deleteError.value='';try{await api('/me/runner/media/'+deleteItem.value.id,{method:'DELETE'});notice.value='收藏已删除';deleteDialog.value.close();await load();}catch(err){deleteError.value=err.message;}finally{deleting.value=false;}}
const deviceBusy=ref(''),deviceMessage=ref(''),deviceFailed=ref(false),disconnectDialog=ref(null),disconnectItem=ref(null),disconnectError=ref('');
const activityConsentDialog=ref(null);
let pendingActivityFile=null;
const deviceStatus=status=>({available:'可连接',connected:'已连接',error:'同步异常',revoked:'已解除'}[status]||'待开通');
function runTypeLabel(run){return run.typeLabel||({road:'户外跑',trail:'越野',treadmill:'跑步机',indoor:'室内跑',track:'操场跑',virtual:'虚拟跑',unknown:'跑步·待确认'})[run.runMode]||(run.type==='trail'?'越野跑':'跑步');}
function syncTime(value){if(!value)return'';const raw=String(value);if(!/(Z|[+-]\d{2}:?\d{2})$/.test(raw))return raw.replace('T',' ').slice(0,16);const ms=Date.parse(raw);return Number.isFinite(ms)?new Date(ms+8*3600000).toISOString().slice(0,16).replace('T',' ')+' 北京时间':'';}
function deviceSession(token){return !unmounted&&token===localStorage.getItem('marathon_token');}
async function importActivity(event){
  const file=event.target.files?.[0];event.target.value='';if(!file||deviceBusy.value)return;
  deviceMessage.value='';deviceFailed.value=false;
  if(!/\.(fit|tcx)$/i.test(file.name)){deviceFailed.value=true;deviceMessage.value='请选择 FIT 或 TCX 运动文件';return;}
  if(file.size>5*1024*1024){deviceFailed.value=true;deviceMessage.value='运动文件不能超过 5 MB';return;}
  if(!file.size){deviceFailed.value=true;deviceMessage.value='文件内容为空，请重新导出';return;}
  const token=localStorage.getItem('marathon_token');if(!token||unmounted)return;
  pendingActivityFile={file,token,view:view.value};deviceBusy.value='consent';activityConsentDialog.value.showModal();
}
function cancelActivityFileConsent(){pendingActivityFile=null;if(deviceBusy.value==='consent')deviceBusy.value='';if(activityConsentDialog.value?.open)activityConsentDialog.value.close();}
function onActivityConsentClosed(){if(!activityConsentDialog.value?.open)cancelActivityFileConsent();}
async function acceptActivityFileConsent(){
  const pending=pendingActivityFile;cancelActivityFileConsent();
  if(!pending||!deviceSession(pending.token)||view.value!==pending.view)return;
  const {file,token}=pending;deviceBusy.value='import';
  try{const result=await upload('/me/devices/import',file,{headers:{'X-Activity-Data-Consent':activityConsentVersion}});if(!deviceSession(token))return;deviceMessage.value=result.note||(result.updated?'已补全这场运动，数据已更新。':result.imported?'已导入 1 场运动，数据已更新。':result.duplicates?'这场运动已经记录过了，没有重复计入。':'没有可导入的跑步或越野记录。');deviceFailed.value=!result.imported&&!result.duplicates&&!result.updated;await load();}
  catch(err){if(deviceSession(token)){deviceFailed.value=true;deviceMessage.value=err.message||'导入失败，请重新选择文件';}}
  finally{if(deviceSession(token))deviceBusy.value='';}
}
async function connectDevice(device){if(deviceBusy.value||!['available','revoked'].includes(device.status))return;const token=localStorage.getItem('marathon_token');deviceBusy.value=device.id;deviceMessage.value='';deviceFailed.value=false;try{const result=await api('/me/devices/'+encodeURIComponent(device.id)+'/connect');if(!deviceSession(token))return;const url=new URL(result.url);if(url.protocol!=='https:')throw new Error('授权地址暂不可用');window.location.assign(url.href);}catch(err){if(deviceSession(token)){deviceFailed.value=true;deviceMessage.value=err.message||'暂时无法打开授权';}}finally{if(deviceSession(token))deviceBusy.value='';}}
async function syncDevice(device){if(deviceBusy.value||!['connected','error'].includes(device.status))return;const token=localStorage.getItem('marathon_token');deviceBusy.value=device.id;deviceMessage.value='';deviceFailed.value=false;try{const result=await api('/me/devices/'+encodeURIComponent(device.id)+'/sync',{method:'POST'});if(!deviceSession(token))return;deviceMessage.value=result.imported?`已同步 ${result.imported} 场运动，数据已更新。`:'同步完成，暂时没有新的运动记录。';if(result.rejected)deviceMessage.value+=` ${result.rejected} 条记录未通过校验。`;await load();}catch(err){if(deviceSession(token)){deviceFailed.value=true;deviceMessage.value=err.message||'同步失败，请稍后重试';await load();}}finally{if(deviceSession(token))deviceBusy.value='';}}
